"""Synchronize research documents from the corrected, verified record replay."""
from pathlib import Path
import json,hashlib,shutil
R=Path(__file__).resolve().parent;P=R/'Saved Model/stage2_stage3_translation_audit_v2'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
v=read(P/'verification.json');a=read(P/'analysis_summary.json');assert v['passed'] and v['analysis_sha256']==sha(P/'analysis_summary.json')
paths=['Progress.txt','Current_Model_Explanation.txt','Research Paper/Readiness_and_Evidence.md','Research Paper/BioNutriGPT_Manuscript_v2.md','Research Paper/Stage2_Stage3_Translation_Study_v1.md']
archive=P/'original_documents';archive.mkdir(exist_ok=True)
for name in paths:
    if not (archive/Path(name).name).exists():shutil.copy2(R/name,archive/Path(name).name)
names={'rules_only':'Rules-only','minimum_change':'Minimum-change','model_guided':'Model-guided'}
table='| Method | Verified Stage 3 plans | End-to-end accepted | Conditional success after Stage 2 | Median recorded call time |\n| --- | ---: | ---: | ---: | ---: |\n'
for arm,s in a['arm_summaries'].items():
    table+=f"| {names[arm]} | {s['stage3']}/300 | {s['end_to_end']}/300 | {s['end_to_end']}/{s['stage2_participants']*3} | {s['runtime_median']:.3f} s |\n"
c=a['contrasts'][0];pooled=c['pooled']['end_to_end'];dist=c['distance']
conclusion=f"Reanalysis of 900 existing records (100 participants, three arms and three dietary modes) changed no acceptance decisions. Model-guided versus minimum-change end-to-end acceptance differed by {pooled['mean_difference']:.2f} percentage points (participant-cluster bootstrap 95% CI {pooled['ci95'][0]:.2f} to {pooled['ci95'][1]:.2f}). The earlier pooled exact p-value was invalid because dietary modes were treated as independent people; it is withdrawn. No pooled exact p-value is reported."
mode_table='| Mode: model-guided vs minimum-change end-to-end | Difference (pp) | Exact p | Holm-adjusted p (nine comparisons) |\n| --- | ---: | ---: | ---: |\n'
for mode,s in c['per_mode'].items():
    t=s['end_to_end'];mode_table+=f"| {mode} | {t['mean_difference']:+.2f} | {t['exact_p']:.7f} | {t['holm_p_9']:.7f} |\n"
scope='The protocol did not fix a primary mode or a multiplicity family. This correction is explicitly retrospective: pooled confidence intervals resample 100 participants with their modes together; per-mode exact tests are exploratory, with Holm adjustment across nine mode-by-arm comparisons per binary endpoint. The pointwise 95% intervals are not multiplicity-adjusted. Model-guided versus minimum-change is not significant at .05 in any individual mode after this adjustment. This does not prove equivalence.'
status='Archived solver metadata show 881 time-limited solves with independently verified plans, 12 solver-status-0 results, three solver-reported infeasibilities and four timeouts without a verified plan. Status 0 is interpreted under the configured solver gap tolerance (1%), not as an independently proven exact optimum. The audit does not rerun or independently certify infeasibility. All 893 returned baskets passed fresh arithmetic and structural checks.'
contract='With active nutrient slack fixed to zero and the same energy prescription and bounds, arm-specific non-energy targets do not change the effective selection objective or mathematical feasible set. They can affect coefficients on fixed-zero slack variables, so the unreduced numerical model need not be byte-identical. Identical problems also need not produce identical incumbents within a time limit. Only 274 of 300 participant-mode groups had identical baskets across all three arms; 26 differed. The one-plan operational difference is not evidence that model guidance expands feasibility. End-to-end differences primarily inherit the upstream model-score gate, with a one-cell downstream timeout difference.'
distance=f"The original all-field weighted distance is withdrawn from comparative interpretation: it was incorrectly labeled as using Stage 2 scales and active nutrients. A new explicitly post-hoc metric uses all {len(a['active_nutrients'])} active nutrients, the exact fixed Stage 2 scales and only jointly successful participant-mode pairs. Unknown contributions are excluded rather than treated as known zero. Model-guided minus minimum-change paired mean distance difference: {dist['mean_difference']:.4f}, pointwise bootstrap 95% CI [{dist['ci95'][0]:.4f}, {dist['ci95'][1]:.4f}], over {dist['n_participants']} participants and {dist['n_joint_success_cells']} paired mode cells. Each participant contributes the mean over their available matched modes. This exploratory geometric difference is not evidence of better meals or clinical benefit; it compares distances to different target vectors. Per-nutrient absolute errors and units are retained locally."
report='# Stage 2 to Stage 3 translation: corrected existing-record audit v2\n\nUpdated 23 November 2026. No solver rerun, model retraining or architecture change. Original study records and historical document copies are preserved.\n\n## Corrected findings\n\n'+conclusion+'\n\n'+table+'\nThe 300 cells per arm are repeated dietary-mode evaluations of 100 people, not 300 independent participants. Conditional denominators are displayed separately and are not the primary paired comparison.\n\n'+mode_table+'\n'+scope+'\n\n## Solver classification\n\n'+status+'\n\nThe approximately 3.03-second medians describe recorded call durations, not proof of optimal solutions. The original aggregate wall time is historical runtime metadata; it cannot be independently reconstructed by summing concurrent task durations. No new wall-clock benchmark is claimed.\n\n## Architecture interpretation\n\n'+contract+'\n\n## Target-distance correction\n\n'+distance+'\n\n## Verification performed\n\nThe new replay reconstructs inputs from the unchanged Stage 2 checkpoints and participant metadata, checks all 900 input fingerprints, recalculates food quantities, integrality, category/serving limits, dietary exclusions, active nutrient coverage and bounds, energy, macro fractions, fiber density and sodium/potassium checks. It recomputes Stage 3 acceptance instead of trusting saved flags. Stage 2 gate decisions are recomputed from saved verified probabilities and nutrient vectors; neural inference is not repeated.\n\nMaximum nutrient accounting residual: '+f"{a['max_accounting_residual']:.9g}"+'; acceptance mismatches: zero. Five corruption/safeguard checks passed (invalid serving count, changed nutrient total, changed bound, false saved acceptance flag and unknown food ID). A separate statistics implementation verified 27 paired confidence intervals, 18 exact tests, both Holm-adjustment families, distances, counts and timing summaries.\n\nShared dependencies are disclosed: food parsing, Stage 2 bound construction, rule metadata and fingerprint serialization use existing helpers. Basket acceptance logic and statistical replay are separately implemented. This does not validate the underlying catalog measurements or clinical appropriateness.\n\n## Provenance limits\n\nCurrent hashes match the historical source bindings. All original JSON artifacts and upstream checkpoints remained unchanged throughout replay. The historical runner rewrote its protocol and did not bind its own source or all upstream checkpoints; retrospective replay cannot establish that a prospectively immutable protocol existed. The new audit captures an input hash manifest and source hashes but does not erase that limitation. These are reused US profiles, not Indian prediction validation.\n\n## Evidence files\n\n`Saved Model/stage2_stage3_translation_audit_v2/` contains input_manifest.json, recomputed_records_LOCAL.json, acceptance_mismatches.json, analysis_summary.json, replay_verification.json and verification.json. The original 900 checkpoints remain in `Saved Model/stage2_stage3_translation_study_v1/checkpoints/`.\n\n## Next decision\n\nThis repair is complete. Testing an explicit target-deviation objective in Stage 3 would be a separate architectural experiment, with the present bounds-based objective as comparator. It has not been implemented or run by this audit.\n'
(R/'Research Paper/Stage2_Stage3_Translation_Audit_v2.md').write_text(report,encoding='utf-8')
(R/'Research Paper/Stage2_Stage3_Translation_Study_v1.md').write_text('# Historical translation study v1 — superseded interpretation\n\nUse [corrected audit v2](Stage2_Stage3_Translation_Audit_v2.md). The original report is preserved at `Saved Model/stage2_stage3_translation_audit_v2/original_documents/Stage2_Stage3_Translation_Study_v1.md`. Original study JSON artifacts remain unchanged. Solver-status claims, pooled p-values, identical-basket claims, target-distance interpretation and verification scope required correction.\n',encoding='utf-8')
note='STAGE 2 TO STAGE 3 EXISTING-RECORD AUDIT v2 — 2026-11-23\n'+conclusion+'\n'+status+'\nFresh checks verified all 900 records; 27 intervals and 18 exact tests were independently recomputed. Five corruption checks passed. No solver rerun or architecture change. Report: Research Paper/Stage2_Stage3_Translation_Audit_v2.md. Evidence: Saved Model/stage2_stage3_translation_audit_v2/. Historical v1 pooled p-values and optimality claims are superseded.\n\n'
for name in ['Progress.txt','Current_Model_Explanation.txt']:
    p=R/name;text=p.read_text(encoding='utf-8-sig');marker='STAGE 2 COMPARISON CORRECTION v2';assert marker in text
    p.write_text(note+text[text.index(marker):],encoding='utf-8')
p=R/'Research Paper/Readiness_and_Evidence.md';text=p.read_text(encoding='utf-8-sig');marker='## Corrected Stage 2 comparison';assert marker in text
p.write_text('## Corrected translation audit — 23 November 2026\n\n'+note.split('\n',1)[1]+text[text.index(marker):],encoding='utf-8')
p=R/'Research Paper/BioNutriGPT_Manuscript_v2.md';text=p.read_text(encoding='utf-8-sig');start=text.index('### 3.4 Stage 2 to Stage 3');end=text.index('### 3.5 Historical optimizer',start)
section='### 3.4 Stage 2 to Stage 3 translation: corrected retrospective audit\n\n'+conclusion+'\n\n'+table+'\n'+status+'\n\n'+contract+'\n\n'+mode_table+'\n'+scope+'\n\n'+distance+'\n\nFresh arithmetic and structural replay verified all 900 records; independent statistical replay checked 27 intervals and 18 exact tests. Historical protocol-freezing limitations remain, and these results do not establish clinical benefit or Indian external validity. See Stage2_Stage3_Translation_Audit_v2.md for the amendment, scope and verification receipts.\n\n'
p.write_text(text[:start]+section+text[end:],encoding='utf-8')
receipt={'completed':True,'solver_calls':0,'verification_sha256':sha(P/'verification.json'),'documents':{name:sha(R/name) for name in paths+['Research Paper/Stage2_Stage3_Translation_Audit_v2.md']}}
(P/'document_sync.json').write_text(json.dumps(receipt,indent=2))
print(conclusion);print(table)
